// Bookmark Manager API — entrypoint
// See PRODUCT_SPEC.md for full requirements
// The agent will build this out across tasks T1-T6

import express from "express";
import Database from "better-sqlite3";

const app = express();
const PORT = 3000;
const db = new Database("data.db");
db.pragma("foreign_keys = ON");

app.use(express.json());

type Bookmark = {
  id: number;
  url: string;
  title: string;
  description: string | null;
  folder_id: number | null;
  created_at: string;
  updated_at: string;
};

type Folder = {
  id: number;
  name: string;
  created_at: string;
  updated_at: string;
};

db.exec(`
  CREATE TABLE IF NOT EXISTS folders (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS bookmarks (
    id INTEGER PRIMARY KEY,
    url TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    folder_id INTEGER,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (folder_id) REFERENCES folders(id)
  )
`);

const bookmarkColumns = db.prepare("PRAGMA table_info(bookmarks)").all() as Array<{ name: string }>;
if (!bookmarkColumns.some((column) => column.name === "folder_id")) {
  db.exec("ALTER TABLE bookmarks ADD COLUMN folder_id INTEGER REFERENCES folders(id)");
}

const selectBookmarkById = db.prepare("SELECT * FROM bookmarks WHERE id = ?");
const selectFolderById = db.prepare("SELECT * FROM folders WHERE id = ?");

function getBookmark(id: number): Bookmark | undefined {
  return selectBookmarkById.get(id) as Bookmark | undefined;
}

function getFolder(id: number): Folder | undefined {
  return selectFolderById.get(id) as Folder | undefined;
}

function parseId(value: string): number | null {
  const id = Number(value);
  return Number.isInteger(id) && id > 0 ? id : null;
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function validateFolderId(value: unknown): string | null {
  if (value === null) {
    return null;
  }

  if (typeof value !== "number" || !Number.isInteger(value) || value <= 0) {
    return "folder_id must be a positive integer or null";
  }

  if (!getFolder(value)) {
    return "folder_id does not reference an existing folder";
  }

  return null;
}

function validateBookmarkInput(body: unknown, required: boolean): string | null {
  if (typeof body !== "object" || body === null) {
    return "Request body must be an object";
  }

  const input = body as Record<string, unknown>;

  if (required || "url" in input) {
    if (!isNonEmptyString(input.url)) {
      return "url is required";
    }
  }

  if (required || "title" in input) {
    if (!isNonEmptyString(input.title)) {
      return "title is required";
    }
  }

  if ("description" in input && input.description !== null && typeof input.description !== "string") {
    return "description must be a string or null";
  }

  if ("folder_id" in input) {
    const folderIdError = validateFolderId(input.folder_id);
    if (folderIdError) {
      return folderIdError;
    }
  }

  return null;
}

app.get("/health", (_req, res) => {
  res.status(200).json({ status: "ok" });
});

app.post("/folders", (req, res) => {
  if (typeof req.body !== "object" || req.body === null || !isNonEmptyString(req.body.name)) {
    return res.status(400).json({ error: "name is required" });
  }

  const now = new Date().toISOString();
  const result = db
    .prepare(
      `
        INSERT INTO folders (name, created_at, updated_at)
        VALUES (?, ?, ?)
      `,
    )
    .run(req.body.name.trim(), now, now);

  res.status(201).json(getFolder(Number(result.lastInsertRowid)));
});

app.get("/folders", (_req, res) => {
  const folders = db.prepare("SELECT * FROM folders ORDER BY id ASC").all() as Folder[];
  res.status(200).json(folders);
});

app.get("/folders/:id", (req, res) => {
  const id = parseId(req.params.id);
  const folder = id === null ? undefined : getFolder(id);

  if (!folder) {
    return res.status(404).json({ error: "Folder not found" });
  }

  const bookmarks = db
    .prepare("SELECT * FROM bookmarks WHERE folder_id = ? ORDER BY id ASC")
    .all(folder.id) as Bookmark[];

  res.status(200).json({ ...folder, bookmarks });
});

app.put("/folders/:id", (req, res) => {
  const id = parseId(req.params.id);
  const folder = id === null ? undefined : getFolder(id);

  if (!folder) {
    return res.status(404).json({ error: "Folder not found" });
  }

  if (typeof req.body !== "object" || req.body === null || !isNonEmptyString(req.body.name)) {
    return res.status(400).json({ error: "name is required" });
  }

  db.prepare("UPDATE folders SET name = ?, updated_at = ? WHERE id = ?").run(
    req.body.name.trim(),
    new Date().toISOString(),
    folder.id,
  );

  res.status(200).json(getFolder(folder.id));
});

app.delete("/folders/:id", (req, res) => {
  const id = parseId(req.params.id);
  const folder = id === null ? undefined : getFolder(id);

  if (!folder) {
    return res.status(404).json({ error: "Folder not found" });
  }

  const deleteFolder = db.transaction((folderId: number) => {
    db.prepare("UPDATE bookmarks SET folder_id = NULL, updated_at = ? WHERE folder_id = ?").run(
      new Date().toISOString(),
      folderId,
    );
    db.prepare("DELETE FROM folders WHERE id = ?").run(folderId);
  });

  deleteFolder(folder.id);
  res.status(204).send();
});

app.post("/bookmarks", (req, res) => {
  const validationError = validateBookmarkInput(req.body, true);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const { url, title, description } = req.body as {
    url: string;
    title: string;
    description?: string | null;
    folder_id?: number | null;
  };
  const now = new Date().toISOString();

  const result = db
    .prepare(
      `
        INSERT INTO bookmarks (url, title, description, folder_id, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?)
      `,
    )
    .run(url.trim(), title.trim(), description ?? null, req.body.folder_id ?? null, now, now);

  const bookmark = getBookmark(Number(result.lastInsertRowid));
  res.status(201).json(bookmark);
});

app.get("/bookmarks", (_req, res) => {
  const bookmarks = db
    .prepare("SELECT * FROM bookmarks ORDER BY id ASC")
    .all() as Bookmark[];

  res.status(200).json(bookmarks);
});

app.get("/bookmarks/:id", (req, res) => {
  const id = parseId(req.params.id);
  const bookmark = id === null ? undefined : getBookmark(id);

  if (!bookmark) {
    return res.status(404).json({ error: "Bookmark not found" });
  }

  res.status(200).json(bookmark);
});

app.put("/bookmarks/:id", (req, res) => {
  const id = parseId(req.params.id);
  const existing = id === null ? undefined : getBookmark(id);

  if (!existing) {
    return res.status(404).json({ error: "Bookmark not found" });
  }

  const validationError = validateBookmarkInput(req.body, false);
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const input = req.body as {
    url?: string;
    title?: string;
    description?: string | null;
    folder_id?: number | null;
  };
  const updatedAt = new Date().toISOString();

  db.prepare(
    `
      UPDATE bookmarks
      SET url = ?, title = ?, description = ?, folder_id = ?, updated_at = ?
      WHERE id = ?

      WHERE id = ?
    `,
  ).run(
    input.url === undefined ? existing.url : input.url.trim(),
    input.title === undefined ? existing.title : input.title.trim(),
    input.description === undefined ? existing.description : input.description,
    input.folder_id === undefined ? existing.folder_id : input.folder_id,
    updatedAt,
    existing.id,
  );

  res.status(200).json(getBookmark(existing.id));
});

app.delete("/bookmarks/:id", (req, res) => {
  const id = parseId(req.params.id);
  const bookmark = id === null ? undefined : getBookmark(id);

  if (!bookmark) {
    return res.status(404).json({ error: "Bookmark not found" });
  }

  db.prepare("DELETE FROM bookmarks WHERE id = ?").run(bookmark.id);
  res.status(204).send();
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

export default app;

